val RequestTiming = createApplicationPlugin("RequestTiming") {
    val startKey = AttributeKey<Long>("start")
    onCall { call -> call.attributes.put(startKey, System.nanoTime()) }
    on(ResponseSent) { call ->
        metrics.record(call.request.path(), System.nanoTime() - call.attributes[startKey])
    }
}

fun Application.module() { install(RequestTiming) }
